<?php
namespace App\Filament\Resources\VietnamProvinces;
use App\Filament\Resources\Concerns\AdminResource;use App\Filament\Resources\VietnamProvinces\Pages\ManageVietnamProvinces;use App\Models\VietnamProvince;
use BackedEnum;use Filament\Actions\EditAction;use Filament\Forms\Components\Select;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;use Illuminate\Database\Eloquent\Builder;
class VietnamProvinceResource extends AdminResource {protected static ?string $model=VietnamProvince::class;protected static string $viewPermission='shipping.view';protected static ?string $managePermission='shipping.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedMap;protected static ?string $navigationLabel='Gán vùng theo tỉnh';protected static string|\UnitEnum|null $navigationGroup='Bán hàng';protected static ?int $navigationSort=45;public static function form(Schema $s):Schema{return $s->components([Select::make('shipping_zone_id')->relationship('shippingZone','name')->label('Khu vực giao hàng')->searchable()->preload()->nullable()]);}public static function table(Table $t):Table{return $t->defaultSort('sort_order')->columns([TextColumn::make('code')->label('Mã'),TextColumn::make('full_name')->label('Tỉnh/Thành')->searchable(),TextColumn::make('shipping_zone_id')->label('ID khu vực')->placeholder('Mặc định')])->recordActions([EditAction::make()->label('Gán khu vực')]);}public static function canCreate():bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageVietnamProvinces::route('/')];}}
